950	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
951	function escapePointerSegment(segment: string): string {
952	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
953	}
954	
955	// 枚举差异的期望描述：列全候选值（JSON 形式，数字 0 与 -0 都写作 0）
956	function enumExpectedText(enumValues: readonly EnumValue[]): string {
957	  return `枚举 ${JSON.stringify(enumValues)} 之一`;
958	}
959	
960	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
961	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
962	// 可空规则：null 被接受时不产生任何子节点差异；非 null 继续检查全部原约束。
963	// 枚举规则：接受集合为“类型及可空集合”与枚举集合的交集——可空不越过枚举
964	// （null 须列入枚举才被接受）；类型错误只报类型差异，不重复报枚举差异。
965	function checkRule(
966	  rule: BodyRule,
967	  value: unknown,
968	  pointer: string,
969	  problems: StructureProblem[],
970	): void {
971	  if (value === null && rule.nullable) {
972	    // 可空不越过枚举：有枚举时 null 仍须在候选集合中
973	    if (rule.kind === 'object' || rule.kind === 'array') {
974	      return;
975	    }
976	    if (rule.enum === undefined || rule.enum.includes(null)) {
977	      return;
978	    }
979	    problems.push({ pointer, expected: enumExpectedText(rule.enum), actual: 'null' });
980	    return;
981	  }
982	  switch (rule.kind) {
983	    case 'string':
984	    case 'boolean':
985	      if (typeof value !== rule.kind) {
986	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
987	        return;
988	      }
989	      break;
990	    case 'null':
991	      if (value !== null) {
992	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
993	      }
994	      return;
995	    case 'number':
996	      if (typeof value !== 'number' || !Number.isFinite(value)) {
997	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
998	        return;
999	      }
1000	      break;
1001	    case 'integer':
1002	      if (!Number.isInteger(value)) {
1003	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
1004	        return;
1005	      }
1006	      break;
1007	    case 'array': {
1008	      if (!Array.isArray(value)) {
1009	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
1010	        return;
1011	      }
1012	      for (let i = 0; i < value.length; i += 1) {
1013	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
1014	      }
1015	      return;
1016	    }
1017	    case 'object': {
1018	      if (!isPlainObject(value)) {
1019	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
1020	        return;
1021	      }
1022	      for (const [name, field] of rule.fields) {
1023	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
1024	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
1025	          if (field.required) {
1026	            problems.push({
1027	              pointer: childPointer,
1028	              expected: `${field.rule.kind}（必填字段）`,
1029	              actual: 'missing',
1030	            });
1031	          }
1032	        } else {
1033	          checkRule(field.rule, value[name], childPointer, problems);
1034	        }
1035	      }
1036	      if (!rule.additionalProperties) {
1037	        for (const key of Object.keys(value)) {
1038	          if (!rule.fields.has(key)) {
1039	            problems.push({
1040	              pointer: `${pointer}/${escapePointerSegment(key)}`,
1041	              expected: '未声明的字段（不允许）',
1042	              actual: jsonTypeOf(value[key]),
1043	            });
1044	          }
1045	        }
1046	      }
1047	      return;
1048	    }
1049	  }
1050	  // 标量枚举：类型检查已通过才核对候选集合（类型错误不重复报枚举错误）；
1051	  // 数字按数值相等（0 与 -0 等价），不做类型转换
1052	  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
1053	    problems.push({
1054	      pointer,
1055	      expected: enumExpectedText(rule.enum),
1056	      actual: JSON.stringify(value),
1057	    });
1058	  }
1059	}
