1465	function collectViolations(
1466	  oldRule: BodyRule,
1467	  newRule: BodyRule,
1468	  pointer: string,
1469	  out: BodyViolation[],
1470	): void {
1471	  const oldAcceptsNull = ruleAcceptsNullValue(oldRule);
1472	  const newAcceptsNull = ruleAcceptsNullValue(newRule);
1473	  if (oldAcceptsNull && !newAcceptsNull) {
1474	    // null 本身就是完整反例；嵌套位置由外层调用方包上必要的父对象与必填字段
1475	    out.push({ pointer, value: null, message: '旧规则接受 null，新规则不接受 null' });
1476	  }
1477	  // type:null 的旧规则只接受 null（上面已比较），没有非 null 值需要再比
1478	  if (oldRule.kind === 'null') {
1479	    return;
1480	  }
1481	  // 枚举仅含 null 项的旧规则同样只接受 null：可比较的只有 null，上面已处理
1482	  if (!hasNonNullAcceptedValues(oldRule)) {
1483	    return;
1484	  }
1485	  // 新规则只接受 null：旧规则的任意非 null 样本都是反例
1486	  if (newRule.kind === 'null') {
1487	    out.push({
1488	      pointer,
1489	      value: sampleValue(oldRule),
1490	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 null`,
1491	    });
1492	    return;
1493	  }
1494	
1495	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
1496	    // 新规则是标量：旧规则为对象/数组时任何样本都被拒绝
1497	    if (oldRule.kind === 'object' || oldRule.kind === 'array') {
1498	      out.push({
1499	        pointer,
1500	        value: sampleValue(oldRule),
1501	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1502	      });
1503	      return;
1504	    }
1505	    collectScalarViolations(oldRule, newRule, pointer, out);
1506	    return;
1507	  }
1508	
1509	  if (newRule.kind === 'array') {
1510	    if (oldRule.kind !== 'array') {
1511	      out.push({
1512	        pointer,
1513	        value: sampleValue(oldRule),
1514	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
1515	      });
1516	      return;
1517	    }
1518	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
1519	    const sub: BodyViolation[] = [];
1520	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
1521	    for (const s of sub) {
1522	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
1523	    }
1524	    return;
1525	  }
1526	
1527	  // newRule.kind === 'object'
1528	  if (oldRule.kind !== 'object') {
1529	    out.push({
1530	      pointer,
1531	      value: sampleValue(oldRule),
1532	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
1533	    });
1534	    return;
1535	  }
1536	
1537	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
1538	  for (const [name, newField] of newRule.fields) {
1539	    if (!newField.required) {
1540	      continue;
1541	    }
1542	    const oldField = oldRule.fields.get(name);
1543	    if (!oldField || !oldField.required) {
1544	      out.push({
1545	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1546	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
1547	        value: sampleValue(oldRule),
1548	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
1549	      });
1550	    }
1551	  }
1552	
1553	  // (b) 旧规则声明的字段，在新规则下仍须被接受
1554	  for (const [name, oldField] of oldRule.fields) {
1555	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
1556	    const newField = newRule.fields.get(name);
1557	    if (!newField) {
1558	      if (!newRule.additionalProperties) {
1559	        out.push({
1560	          pointer: childPointer,
1561	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
1562	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
1563	        });
1564	      }
1565	      continue;
1566	    }
1567	    const sub: BodyViolation[] = [];
1568	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
1569	    for (const s of sub) {
1570	      out.push({
1571	        pointer: s.pointer,
1572	        message: s.message,
1573	        value: sampleObjectWith(oldRule, name, s.value),
1574	      });
1575	    }
1576	  }
1577	
1578	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
1579	  if (oldRule.additionalProperties) {
1580	    if (!newRule.additionalProperties) {
1581	      const name = freshFieldName(oldRule.fields, newRule.fields);
1582	      out.push({
1583	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1584	        value: sampleObjectWith(oldRule, name, 0),
1585	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
1586	      });
1587	    } else {
1588	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
1589	      for (const [name, newField] of newRule.fields) {
1590	        if (oldRule.fields.has(name)) {
1591	          continue;
1592	        }
1593	        out.push({
1594	          pointer: `${pointer}/${escapePointerSegment(name)}`,
1595	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
1596	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
1597	        });
1598	      }
1599	    }
1600	  }
1601	}
