1604	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
1605	  if (endpoint.bodyRule) {
1606	    return {
1607	      method: endpoint.method,
1608	      path: endpoint.path,
1609	      headers: { 'Content-Type': 'application/json' },
1610	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
1611	    };
1612	  }
1613	  return { method: endpoint.method, path: endpoint.path, headers: {}, body: '' };
