2633	    const pathWhere = `paths[${JSON.stringify(ep.path)}]`;
2634	    if (!isPlainObject(pathItem)) {
2635	      importFail(ctx, pathWhere, '必须是对象');
2636	    }
2637	    const methodKey = ep.method.toLowerCase();
2638	    if (!hasOwnKey(pathItem, methodKey)) {
2639	      importFail(ctx, pathWhere, `${label} 缺少对应操作：${methodKey} 操作不存在`);
2640	    }
2641	    const operation = (pathItem as Record<string, unknown>)[methodKey];
2642	    const opWhere = `${pathWhere}.${methodKey}`;
2643	    if (!isPlainObject(operation)) {
