2659	    // 仅替换 requestBody：保留接口顺序、branches（分支、顺序与响应原样）与 responses
2660	    const out: {
2661	      method: string;
2662	      path: string;
2663	      requestBody?: unknown;
2664	      branches?: unknown;
2665	      responses: unknown;
2666	    } = {
2667	      method: ep.method,
2668	      path: ep.path,
2669	      responses: ep.responses,
