2819	    );
2820	  }
2821	  if (!Array.isArray(rawHeaders)) {
2822	    snapshotFail(`${reqWhere}.rawHeaders`, '必须是按在线顺序成对排列的字符串数组');
2823	  }
2824	  if (rawHeaders.length % 2 !== 0) {
2825	    snapshotFail(
2826	      `${reqWhere}.rawHeaders`,
2827	      `必须成对（名称、值交替），当前长度为 ${rawHeaders.length}`,
2828	    );
2829	  }
2830	  for (let j = 0; j < rawHeaders.length; j += 1) {
2831	    if (typeof rawHeaders[j] !== 'string') {
