3008	  const requestsFile = path.resolve(requestsArg);
3009	  const configFile = path.resolve(configArg);
3010	
3011	  const attemptSnapshot = async (): Promise<{ requests?: SnapshotRequest[]; error?: string }> => {
3012	    try {
3013	      return { requests: await loadSnapshotFromFile(requestsFile) };
3014	    } catch (e) {
3015	      return { error: describeError(e) };
3016	    }
3017	  };
3018	  const attemptSpecs = async (): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
3019	    try {
3020	      return { specs: await loadSpecsFromFile(configFile) };
3021	    } catch (e) {
3022	      return { error: describeError(e) };
3023	    }
