3025	
3026	  // 两份输入都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
3027	  const [snapResult, specResult] = await Promise.all([attemptSnapshot(), attemptSpecs()]);
3028	  let failed = false;
3029	  if (snapResult.error !== undefined) {
3030	    process.stderr.write(`${APP_NAME}: verify 请求快照：${snapResult.error}\n`);
3031	    failed = true;
