3091	// 一条待重放的请求：共享快照校验之上再经重放专用校验
3092	interface ReplayRequest {
3093	  readonly id: number;
3094	  readonly method: 'GET' | 'POST';
3095	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
3096	  readonly target: string;
3097	  // target 去掉查询串后的字面路径（比较策略按“方法 + 路径”选择接口）
3098	  readonly path: string;
3099	  // 过滤后的业务头：名称大小写、重复项与在线顺序原样保留
3100	  readonly headers: readonly [string, string][];
3101	  readonly body: Buffer;
3102	  readonly plannedStatus: number;
3103	  readonly plannedBody: string;
3104	}
