3169	  const base = parseSnapshotRecord(raw, index, seen);
3170	
3171	  if (base.method !== 'GET' && base.method !== 'POST') {
3172	    snapshotFail(
3173	      `${where}.request.method`,
3174	      `仅支持重放 GET/POST，收到 ${JSON.stringify(base.method)}`,
3175	    );
3176	  }
3177	  validateReplayTarget(base.target, `${where}.request.target`);
3178	  if (base.path === ADMIN_BASE || base.path.startsWith(ADMIN_PREFIX)) {
3179	    snapshotFail(
3180	      `${where}.request.target`,
3181	      `指向管理入口（${ADMIN_BASE} 本身及 ${ADMIN_PREFIX} 前缀），禁止重放`,
3182	    );
3183	  }
3184	
3185	  // 每条记录另须有 200–599 的计划响应状态与文本正文（比较基准）
3186	  const prWhere = `${where}.plannedResponse`;
3187	  const planned = (raw as Record<string, unknown>).plannedResponse;
3188	  if (!isPlainObject(planned)) {
3189	    snapshotFail(prWhere, '必须是对象（重放需要计划响应状态与文本正文）');
3190	  }
3191	  const { status, body } = planned;
3192	  if (!Number.isInteger(status) || (status as number) < 200 || (status as number) > 599) {
3193	    snapshotFail(
3194	      `${prWhere}.status`,
3195	      `必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`,
3196	    );
3197	  }
3198	  if (typeof body !== 'string') {
3199	    snapshotFail(`${prWhere}.body`, '必须是文本字符串');
3200	  }
3201	  if (hasLoneSurrogate(body as string)) {
3202	    snapshotFail(
3203	      `${prWhere}.body`,
3204	      '含孤立代理项（lone surrogate）：按 UTF-8 编码会被替换字符改写，无法作为无损的比较基准',
3205	    );
3206	  }
3207	
3208	  return {
3209	    id: base.id,
3210	    method: base.method,
3211	    target: base.target,
3212	    path: base.path,
3213	    headers: filterReplayHeaders(base.rawHeaders, `${where}.request.rawHeaders`),
3214	    body: base.body,
3215	    plannedStatus: status as number,
3216	    plannedBody: body as string,
3217	  };
3218	}
