3312	function parseStrategyEndpoint(
3313	  raw: unknown,
3314	  index: number,
3315	  seen: Set<string>,
3316	  endpoints: Map<string, JsonCompareEndpoint>,
3317	): void {
3318	  const where = `endpoints[${index}]`;
3319	  if (!isPlainObject(raw)) {
3320	    throw new ConfigError(`${where} 必须是对象`);
3321	  }
3322	  for (const key of Object.keys(raw)) {
3323	    if (key !== 'method' && key !== 'path' && key !== 'ignore' && key !== 'align') {
3324	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
3325	    }
3326	  }
3327	  const { method, path: routePath, ignore, align } = raw;
3328	  if (method !== 'GET' && method !== 'POST') {
3329	    throw new ConfigError(
3330	      `${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`,
3331	    );
3332	  }
3333	  if (typeof routePath !== 'string') {
3334	    throw new ConfigError(`${where}.path 必须是字符串`);
3335	  }
3336	  validatePath(routePath, where);
3337	
3338	  const ignoreSet = new Set<string>();
3339	  if (ignore !== undefined) {
3340	    if (!Array.isArray(ignore)) {
3341	      throw new ConfigError(`${where}.ignore 必须是 RFC 6901 指针字符串数组`);
3342	    }
3343	    ignore.forEach((rawPointer, j) => {
3344	      // 支持根（""）、空字段名（"/"）、__proto__ 与 ~0/~1 转义；
3345	      // 重复或父子重叠的忽略项不改变结果（集合语义）
3346	      const segments = parseJsonPointer(rawPointer, `${where}.ignore[${j}]`, '忽略指针');
3347	      ignoreSet.add(canonicalPointer(segments));
3348	    });
3349	  }
3350	
3351	  // 数组业务键对齐：互不嵌套的数组位置各指定一个元素自有字段作键；
3352	  // 重复位置、嵌套位置或非法配置整份拒绝
3353	  const alignMap = new Map<string, AlignSpec>();
3354	  if (align !== undefined) {
3355	    if (!Array.isArray(align)) {
3356	      throw new ConfigError(`${where}.align 必须是数组（元素为含 pointer 与 key 的对象）`);
3357	    }
3358	    align.forEach((entry, j) => {
3359	      const entryWhere = `${where}.align[${j}]`;
3360	      if (!isPlainObject(entry)) {
3361	        throw new ConfigError(`${entryWhere} 必须是对象（含 pointer 与 key）`);
3362	      }
3363	      for (const key of Object.keys(entry)) {
3364	        if (key !== 'pointer' && key !== 'key') {
3365	          throw new ConfigError(`${entryWhere} 含未知字段 "${key}"`);
3366	        }
3367	      }
3368	      // 位置为 RFC 6901 指针：支持根（""）、空字段名、__proto__ 与 ~0/~1 转义
3369	      const segments = parseJsonPointer(entry.pointer, `${entryWhere}.pointer`, '对齐位置指针');
3370	      if (typeof entry.key !== 'string') {
3371	        throw new ConfigError(
3372	          `${entryWhere}.key 必须是字符串（元素自有字段名，可为空名或 "__proto__"），收到 ${JSON.stringify(entry.key)}`,
3373	        );
3374	      }
3375	      const canonical = canonicalPointer(segments);
3376	      if (alignMap.has(canonical)) {
3377	        throw new ConfigError(
3378	          `${entryWhere}.pointer ${JSON.stringify(entry.pointer)} 与同一接口的另一个对齐位置重复`,
3379	        );
3380	      }
3381	      for (const existing of alignMap.values()) {
3382	        if (isPrefixSegments(existing.segments, segments) || isPrefixSegments(segments, existing.segments)) {
3383	          throw new ConfigError(
3384	            `${entryWhere}.pointer ${JSON.stringify(entry.pointer)} 与对齐位置 ${JSON.stringify(existing.pointer)} 互相嵌套：对齐位置必须互不嵌套`,
3385	          );
3386	        }
3387	      }
3388	      alignMap.set(canonical, { pointer: canonical, segments, key: entry.key });
3389	    });
3390	  }
3391	
3392	  const key = `${method as string} ${routePath}`;
3393	  if (seen.has(key)) {
3394	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
3395	  }
3396	  seen.add(key);
3397	  endpoints.set(key, { ignore: ignoreSet, align: alignMap });
3398	}
