3400	function parseCompareStrategy(raw: unknown): JsonCompareStrategy {
3401	  if (!isPlainObject(raw)) {
3402	    throw new ConfigError('比较策略顶层必须是 JSON 对象（含 endpoints）');
3403	  }
3404	  for (const key of Object.keys(raw)) {
3405	    if (key !== 'endpoints') {
3406	      throw new ConfigError(`比较策略顶层含未知字段 "${key}"`);
3407	    }
3408	  }
3409	  const { endpoints } = raw;
3410	  if (!Array.isArray(endpoints)) {
