4022	        const checked = checkAlignTarget(actual.value, spec);
4023	        if (checked === null) {
4024	          continue; // 位置不存在允许
4025	        }
4026	        if ('problem' in checked) {
4027	          alignProblems.push(checked.problem);
4028	        } else {
4029	          actualKeys.set(spec.pointer, checked.keys);
4030	        }
4031	      }
4032	      const out: BodyDiffOut = { differences: [], aligned: [] };
4033	      diffJsonValues(
4034	        plan.planned,
4035	        actual.value,
4036	        {
4037	          ignore: plan.endpoint.ignore,
4038	          align: plan.endpoint.align,
4039	          plannedKeys: plan.plannedKeys,
4040	          actualKeys,
4041	        },
4042	        [],
4043	        [],
4044	        out,
4045	      );
4046	      bodyDiff =
4047	        out.differences.length > 0 || out.aligned.length > 0 || alignProblems.length > 0;
4048	      if (out.differences.length > 0) {
4049	        bodyDifferences = out.differences;
4050	      }
4051	      if (out.aligned.length > 0) {
4052	        alignedDifferences = out.aligned;
4053	      }
4054	      if (alignProblems.length > 0) {
4055	        alignmentErrors = alignProblems;
4056	      }
4057	    }
4058	    if (!statusDiff && !bodyDiff) {
4059	      results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
4060	    } else {
4061	      results.push({
4062	        id: request.id,
4063	        outcome: 'different',
4064	        differences: { status: statusDiff, body: bodyDiff },
4065	        // 差异项保留计划与实际正文的无损表示
4066	        ...(bodyDifferences === undefined ? {} : { bodyDifferences }),
4067	        ...(alignedDifferences === undefined ? {} : { alignedDifferences }),
4068	        ...(alignmentErrors === undefined ? {} : { alignmentErrors }),
4069	        ...(bodyError === undefined ? {} : { bodyError }),
4070	        planned: {
4071	          status: request.plannedStatus,
4072	          body: { encoding: 'utf-8', content: request.plannedBody },
4073	        },
4074	        response: replayResponseJson(response),
4075	      });
4076	    }
4077	  }
4078	
4079	  const same = results.filter((r) => r.outcome === 'same').length;
4080	  const different = results.filter((r) => r.outcome === 'different').length;
4081	  const failed = results.filter((r) => r.outcome === 'failed').length;
4082	  const report: ReplayReport = {
4083	    requestsFile,
4084	    port,
4085	    timeoutMs,
4086	    total: results.length,
4087	    same,
4088	    different,
4089	    failed,
4090	    results,
4091	  };
4092	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
4093	  // 空快照或全部相同退出 0；存在差异或通信失败退出 1
4094	  process.exit(different === 0 && failed === 0 ? 0 : 1);
4095	}
