4175	// 找不到见证正文的哨兵：不能用 null——根可空时 JSON null 本身就是合法见证
4176	const NO_WITNESS: unique symbol = Symbol('reach-no-witness');
4177	type Witness = unknown | typeof NO_WITNESS;
4178	
4179	// 标量条件的非 null 值是否满足字段标量规则的“类型”部分（不做类型转换）
4180	function scalarTypeConforms(
4181	  rule: Extract<BodyRule, { kind: ScalarKind }>,
4182	  value: string | number | boolean,
4183	): boolean {
4184	  switch (rule.kind) {
4185	    case 'string':
4186	      return typeof value === 'string';
4187	    case 'boolean':
4188	      return typeof value === 'boolean';
4189	    case 'number':
4190	      return typeof value === 'number' && Number.isFinite(value);
4191	    case 'integer':
4192	      return Number.isInteger(value);
4193	    case 'null':
4194	      return false;
4195	  }
4196	}
4197	
4198	// 条件值与标量字段规则的矛盾原因；无矛盾返回 null。
4199	// 严格按现有语义：类型不符只报类型；类型相符但不在枚举报枚举；
4200	// null 仅当规则接受 null（nullable 且枚举含 null，或 type:"null"）才可行。
4201	function scalarConditionConflict(
4202	  rule: Extract<BodyRule, { kind: ScalarKind }>,
4203	  value: BranchConditionValue,
4204	): { kind: 'type' | 'enum' | 'null' } | null {
4205	  if (value === null) {
4206	    return ruleAcceptsNullValue(rule) ? null : { kind: 'null' };
4207	  }
4208	  if (!scalarTypeConforms(rule, value)) {
4209	    return { kind: 'type' };
4210	  }
4211	  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
4212	    return { kind: 'enum' };
4213	  }
4214	  return null;
4215	}
4216	
4217	// 标量维度的一个与全部被引用常量都不同的合格“其余值”（枚举取未被引用候选；
4218	// 无枚举时构造）。任意两个未被引用的合格值对全部等值条件不可区分，故该代表
4219	// 值与缺失、null 一起构成精确有限域，不是抽样；没有合格其余值时返回 undefined。
4220	function freshScalarValue(
4221	  rule: Extract<BodyRule, { kind: ScalarKind }>,
4222	  referenced: ReadonlySet<unknown>,
4223	): unknown {
4224	  if (rule.enum !== undefined) {
4225	    return rule.enum.find((candidate) => candidate !== null && !referenced.has(candidate));
4226	  }
4227	  if (rule.kind === 'boolean') {
4228	    return !referenced.has(false) ? false : !referenced.has(true) ? true : undefined;
4229	  }
4230	  if (rule.kind === 'null') {
4231	    return undefined;
4232	  }
4233	  if (rule.kind === 'string') {
4234	    for (let i = 0; ; i += 1) {
4235	      const candidate = i === 0 ? 'contractlab' : `contractlab_${i}`;
4236	      if (!referenced.has(candidate)) {
4237	        return candidate;
4238	      }
4239	    }
4240	  }
4241	  // number / integer：取未被引用的最小非负整数（integer 合法；number 也合法）
4242	  for (let i = 0; ; i += 1) {
4243	    if (!referenced.has(i)) {
4244	      return i;
4245	    }
4246	  }
4247	}
