4249	// 约束树节点：根对象或某个被条件经多段指针穿过的中间 object 字段。
4250	// 共享祖先的全部条件（作用于同一对象的字段指针）汇聚到同一节点，
4251	// 例如 /buyer/state 与 /buyer/flag 的 buyer 是同一节点，不能把叶字段视为
4252	// 互相独立的顶层维度。
4253	class ReachNode {
4254	  readonly objectRule: Extract<BodyRule, { kind: 'object' }>;
4255	  // 从根到本节点的对象字段名序列（根为空数组）
4256	  readonly path: readonly string[];
4257	  readonly parent: ReachNode | null;
4258	  // 本节点挂在父对象上的字段名（根为 null）
4259	  readonly fieldName: string | null;
4260	  // 本对象上被条件直接引用的标量子字段名 -> 该字段的标量规则
4261	  readonly scalarFields = new Map<string, Extract<BodyRule, { kind: ScalarKind }>>();
4262	  // 本对象上被条件穿过的 object 子字段名 -> 子节点
4263	  readonly children = new Map<string, ReachNode>();
4264	
4265	  constructor(
4266	    objectRule: Extract<BodyRule, { kind: 'object' }>,
4267	    path: readonly string[],
4268	    parent: ReachNode | null,
4269	    fieldName: string | null,
4270	  ) {
4271	    this.objectRule = objectRule;
4272	    this.path = path;
4273	    this.parent = parent;
4274	    this.fieldName = fieldName;
4275	  }
4276	}
