4278	// 钉值：某 RFC 6901 指针处必须严格等于某常量。以规范指针串为键，
4279	// 使不同分支在同一指针上的钉值可以比较/合并。
4280	interface ReachPin {
4281	  readonly pointer: string;
4282	  readonly segments: readonly string[];
4283	  readonly value: BranchConditionValue;
4284	}
4285	type PinMap = ReadonlyMap<string, ReachPin>;
4286	
4287	// 一支的条件分析：无矛盾时给出指针 -> 常量的钉值表；矛盾时给出按完整
4288	// RFC 6901 指针定位的原因。
4289	interface BranchAnalysis {
4290	  readonly ok: boolean;
4291	  readonly pins?: PinMap;
4292	  readonly reasons?: readonly ReachReason[];
4293	}
4294	
4295	// 同一标量维度上的多个条件常量必须两两严格相等（0 与 -0 视为相等）。
4296	function distinctConstants(values: readonly BranchConditionValue[]): BranchConditionValue[] {
4297	  const distinct: BranchConditionValue[] = [];
4298	  for (const v of values) {
4299	    if (!distinct.some((d) => d === v)) {
4300	      distinct.push(v);
4301	    }
4302	  }
4303	  return distinct;
4304	}
4305	
4306	// 重建节点 + 叶字段名对应的规范 RFC 6901 指针
4307	function reachPointer(node: ReachNode, leafName: string): string {
4308	  return `/${[...node.path, leafName].map(escapePointerSegment).join('/')}`;
4309	}
4310	
4311	function analyzeBranchConditions(branch: BranchSpec, rootNode: ReachNode): BranchAnalysis {
4312	  // 以“所在节点 + 叶字段名”（即规范指针）为标量维度聚合一支的全部常量
4313	  const groups = new Map<string, {
4314	    node: ReachNode;
4315	    name: string;
4316	    values: BranchConditionValue[];
4317	  }>();
4318	  for (const condition of branch.conditions) {
4319	    let node = rootNode;
4320	    for (let k = 0; k < condition.segments.length - 1; k += 1) {
4321	      node = node.children.get(condition.segments[k]) as ReachNode;
4322	    }
4323	    const name = condition.segments[condition.segments.length - 1];
4324	    const key = reachPointer(node, name);
4325	    const group = groups.get(key);
4326	    if (group === undefined) {
4327	      groups.set(key, { node, name, values: [condition.value] });
4328	    } else {
4329	      group.values.push(condition.value);
4330	    }
4331	  }
4332	
4333	  const reasons: ReachReason[] = [];
4334	  const pins = new Map<string, ReachPin>();
4335	  for (const [pointer, group] of groups) {
4336	    const scalarRule = group.node.scalarFields.get(group.name) as Extract<BodyRule, { kind: ScalarKind }>;
4337	    const distinct = distinctConstants(group.values);
4338	    if (distinct.length > 1) {
4339	      reasons.push({
4340	        pointer,
4341	        message: `同一指针上的等值条件值 ${JSON.stringify(distinct)} 互不相容（严格相等、不做类型转换），没有正文能同时满足`,
4342	      });
4343	      continue;
4344	    }
4345	
4346	    const value = distinct[0];
4347	    const conflict = scalarConditionConflict(scalarRule, value);
4348	    if (conflict === null) {
4349	      pins.set(pointer, {
4350	        pointer,
4351	        segments: [...group.node.path, group.name],
4352	        value,
4353	      });
4354	      continue;
4355	    }
4356	    if (conflict.kind === 'type') {
4357	      reasons.push({
4358	        pointer,
4359	        message: `条件值 ${JSON.stringify(value)} 与该字段的 ${scalarRule.kind} 规则矛盾（不做类型转换），不存在在此指针处等于该值的合格正文`,
4360	      });
4361	    } else if (conflict.kind === 'enum') {
4362	      reasons.push({
4363	        pointer,
4364	        message: `条件值 ${JSON.stringify(value)} 不在该字段枚举 ${JSON.stringify(scalarRule.enum)} 之中，不存在在此指针处等于该值的合格正文`,
4365	      });
4366	    } else {
4367	      reasons.push({
4368	        pointer,
4369	        message: '条件要求该字段为 JSON null，但字段规则不接受 null；祖先或字段缺失也不等于显式 null，不存在满足该条件的合格正文',
4370	      });
4371	    }
4372	  }
4373	
4374	  return reasons.length === 0 ? { ok: true, pins } : { ok: false, reasons };
4375	}
