4377	// 标量维度：某对象节点上一个被条件引用的标量子字段的取值域。
4378	interface ReachDim {
4379	  readonly node: ReachNode;
4380	  readonly name: string;
4381	  // 字段“存在且非 null”时的代表值（钉值在求解时单独注入，不在此枚举）
4382	  readonly values: readonly unknown[];
4383	  // 显式 JSON null 是否为合格取值（与“缺失”不同）
4384	  readonly nullable: boolean;
4385	  // 字段是否可缺省
4386	  readonly optional: boolean;
4387	}
4388	
4389	// 在根对象规则与全部分支条件之上做精确的有限域可达性求解。
4390	//
4391	// 多段对象指针形成一棵约束树；每个被引用的标量字段是一个维度，取值域为
4392	// {缺失?，null?，各分支钉过的合格常量，一个合格其余值}。中间对象字段按布局
4393	// （缺失?/null?/存在）递归枚举；未被任何条件引用的字段、对象与数组都不在维度
4394	// 中，而以最小合格样本参与——后代必填只在父对象存在且非 null 时才生效。
4395	// 该有限域对等值条件与首支命中精确（不是抽样）：任意两个“其余值”对全部条件
4396	// 不可区分，未引用子树只影响合格性，其最小样本在任一布局下与合格性恒等。
4397	class ReachSolver {
4398	  private readonly rootRule: Extract<BodyRule, { kind: 'object' }>;
4399	  private readonly branches: readonly BranchSpec[];
4400	  private readonly rootNode: ReachNode;
4401	  private readonly dims: readonly ReachDim[];
4402	
4403	  constructor(rootRule: Extract<BodyRule, { kind: 'object' }>, branches: readonly BranchSpec[]) {
4404	    this.rootRule = rootRule;
4405	    this.branches = branches;
4406	    this.rootNode = this.buildTree();
4407	    this.dims = this.buildDims();
4408	  }
4409	
4410	  // 按全部条件建立对象约束树（范围预检已保证字段链合法）。
4411	  private buildTree(): ReachNode {
4412	    const root = new ReachNode(this.rootRule, [], null, null);
4413	    for (const branch of this.branches) {
4414	      for (const condition of branch.conditions) {
4415	        let node = root;
4416	        let objectRule = this.rootRule;
4417	        for (let k = 0; k < condition.segments.length; k += 1) {
4418	          const name = condition.segments[k];
4419	          const field = objectRule.fields.get(name) as FieldRule;
4420	          if (k === condition.segments.length - 1) {
4421	            node.scalarFields.set(name, field.rule as Extract<BodyRule, { kind: ScalarKind }>);
4422	          } else {
4423	            let child = node.children.get(name);
4424	            if (child === undefined) {
4425	              child = new ReachNode(
4426	                field.rule as Extract<BodyRule, { kind: 'object' }>,
4427	                [...node.path, name],
4428	                node,
4429	                name,
4430	              );
4431	              node.children.set(name, child);
4432	            }
4433	            node = child;
4434	            objectRule = field.rule as Extract<BodyRule, { kind: 'object' }>;
4435	          }
4436	        }
4437	      }
4438	    }
4439	    return root;
4440	  }
4441	
4442	  private buildDims(): ReachDim[] {
4443	    // 维度按首次被引用的顺序登记（分支/条件配置顺序），以规范指针去重
4444	    const order: Array<{ pointer: string; segments: readonly string[] }> = [];
4445	    const seen = new Set<string>();
4446	    for (const branch of this.branches) {
4447	      for (const condition of branch.conditions) {
4448	        if (!seen.has(condition.pointer)) {
4449	          seen.add(condition.pointer);
4450	          order.push({ pointer: condition.pointer, segments: condition.segments });
4451	        }
4452	      }
4453	    }
4454	
4455	    return order.map(({ pointer, segments }) => {
4456	      const node = this.nodeOf(segments);
4457	      const name = segments[segments.length - 1];
4458	      const scalarRule = node.scalarFields.get(name) as Extract<BodyRule, { kind: ScalarKind }>;
4459	      const field = node.objectRule.fields.get(name) as FieldRule;
4460	      const ref = new Set<unknown>();
4461	      const values: unknown[] = [];
4462	      const push = (v: unknown): void => {
4463	        if (!ref.has(v)) {
4464	          ref.add(v);
4465	          values.push(v);
4466	        }
4467	      };
4468	      // 各分支钉过且合格的常量
4469	      for (const branch of this.branches) {
4470	        for (const condition of branch.conditions) {
4471	          if (condition.pointer !== pointer) {
4472	            continue;
4473	          }
4474	          if (scalarConditionConflict(scalarRule, condition.value) === null) {
4475	            push(condition.value);
4476	          }
4477	        }
4478	      }
4479	      // 一个与全部钉值不同的合格其余值（无则省略，如枚举候选已被全部钉住）
4480	      const rest = freshScalarValue(scalarRule, ref);
4481	      if (rest !== undefined) {
4482	        push(rest);
4483	      }
4484	      return {
4485	        node,
4486	        name,
4487	        values,
4488	        nullable: ruleAcceptsNullValue(scalarRule),
4489	        optional: !field.required,
4490	      };
4491	    });
4492	  }
