4736	  solve(routePath: string): { branches: BranchReach[]; fallback: FallbackReach } {
4737	    const analyses = this.branches.map((branch) => analyzeBranchConditions(branch, this.rootNode));
4738	
4739	    const branchResults: BranchReach[] = [];
4740	    for (let i = 0; i < this.branches.length; i += 1) {
4741	      const branch = this.branches[i];
4742	      const analysis = analyses[i];
4743	      if (!analysis.ok || analysis.pins === undefined) {
4744	        branchResults.push({ id: branch.id, status: 'contradictory', reasons: analysis.reasons });
4745	        continue;
4746	      }
4747	
4748	      // 存在合格正文首先命中此支？
4749	      const direct = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === i);
4750	      if (direct !== NO_WITNESS) {
4751	        branchResults.push({ id: branch.id, status: 'reachable', example: this.example(direct, routePath) });
4752	        continue;
4753	      }
4754	
4755	      // 满足此支的合格正文必然首先命中某些前序分支——逐支给出共同遮挡者
4756	      const coveredBy: string[] = [];
4757	      for (let j = 0; j < i; j += 1) {
4758	        const prior = analyses[j];
4759	        if (!prior.ok || prior.pins === undefined) {
