4761	        }
4762	        const merged = this.mergePins(analysis.pins, prior.pins);
4763	        if (merged === null) {
4764	          continue;
4765	        }
4766	        // 同时满足 i 与 j、且 j 之前所有分支都不命中（首支恰为 j）的合格正文
4767	        const witness = this.findWitness(merged, (value) => this.firstMatch(value) === j);
4768	        if (witness !== NO_WITNESS) {
4769	          coveredBy.push(this.branches[j].id);
4770	        }
4771	      }
4772	      branchResults.push({
4773	        id: branch.id,
4774	        status: 'covered',
4775	        coveredBy,
4776	        message:
4777	          `存在满足本支全部条件的合格正文，但它们首先命中的都是前序分支；` +
4778	          `前序分支 ${JSON.stringify(coveredBy)} 的命中区域并集已覆盖本支，本支永远不会被首先选中`,
4779	      });
4780	    }
4781	
4782	    // 兜底：存在任何分支都不命中的合格正文（含根为 JSON null）即可达
