4784	    let fallback: FallbackReach;
4785	    if (fallbackBody !== NO_WITNESS) {
4786	      fallback = { status: 'reachable', example: this.example(fallbackBody, routePath) };
4787	    } else {
4788	      const noWitness = NO_WITNESS;
4789	      const coveredBy = this.branches
4790	        .map((branch, j) => {
4791	          const analysis = analyses[j];
4792	          if (!analysis.ok || analysis.pins === undefined) {
4793	            return noWitness;
4794	          }
4795	          const witness = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === j);
