4887	async function runReach(configArg: string, pathArg: string): Promise<never> {
4888	  const configFile = path.resolve(configArg);
4889	
4890	  let specs: EndpointSpec[];
4891	  try {
4892	    specs = await loadSpecsFromFile(configFile);
4893	  } catch (e) {
4894	    process.stderr.write(`${APP_NAME}: reach 场景配置：${describeError(e)}\n`);
4895	    process.exit(2);
4896	  }
4897	
4898	  let report: ReachReport;
4899	  try {
4900	    const { endpoint } = selectReachEndpoint(specs, configFile, pathArg);
4901	    const rootRule = endpoint.bodyRule as Extract<BodyRule, { kind: 'object' }>;
4902	    const result = new ReachSolver(rootRule, endpoint.branches).solve(endpoint.path);
4903	    const unreachableBranches = result.branches.filter((b) => b.status !== 'reachable').length;
4904	    report = {
4905	      configFile,
4906	      method: 'POST',
4907	      path: endpoint.path,
4908	      branches: result.branches,
4909	      fallback: result.fallback,
4910	      unreachableBranches,
4911	    };
4912	  } catch (e) {
4913	    if (e instanceof ReachError) {
4914	      process.stderr.write(`${APP_NAME}: reach: ${e.message}\n`);
4915	      process.exit(2);
4916	    }
4917	    process.stderr.write(`${APP_NAME}: reach 失败：${describeError(e)}\n`);
4918	    process.exit(2);
4919	  }
4920	
4921	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
4922	  // 有不可达分支退出 1；兜底不可达仅作信息，不改变退出码
4923	  process.exit(report.unreachableBranches > 0 ? 1 : 0);
4924	}
