// 完整响应的无损 JSON 表示（与请求记录正文同一套编码规则）
function replayResponseJson(response: ReplayResponse): {
  status: number;
  body: { encoding: 'utf-8' | 'base64'; content: string };
} {
  return { status: response.status, body: encodeBodyLosslessly(response.body) };
}

type ReplayResultEntry =
  | {
      readonly id: number;
      readonly outcome: 'same';
      readonly response: ReturnType<typeof replayResponseJson>;
    }
  | {
      readonly id: number;
      readonly outcome: 'different';
      // 差异点：状态码不同 / 正文不同（可同时为真；JSON 模式下正文按语义比较）
      readonly differences: { readonly status: boolean; readonly body: boolean };
      // 仅 JSON 语义比较模式：两侧均可解析时列出全部未忽略的独立正文差异
      readonly bodyDifferences?: readonly BodyDifference[];
      // 仅 JSON 语义比较模式且配置了对齐：对齐数组内的元素差异明细
      // （业务键、存在侧原正文位置、计划/实际值、双方独立存在性标记）
      readonly alignedDifferences?: readonly AlignedDifference[];
      // 仅 JSON 语义比较模式且配置了对齐：实际完整响应中的对齐数组类型、
      // 元素或键非法（位置 + 原因）；记正文差异并继续，不算通信失败
      readonly alignmentErrors?: readonly AlignProblem[];
      // 仅 JSON 语义比较模式：实际响应正文非 UTF-8 或非 JSON 时的原因
      readonly bodyError?: string;
      readonly planned: ReturnType<typeof replayResponseJson>;
      readonly response: ReturnType<typeof replayResponseJson>;
    }
  | { readonly id: number; readonly outcome: 'failed'; readonly reason: string };

interface ReplayReport {
  readonly requestsFile: string;
  readonly port: number;
  readonly timeoutMs: number;
  readonly total: number;
  readonly same: number;
  readonly different: number;
  readonly failed: number;
  readonly results: readonly ReplayResultEntry[];
}

async function runReplay(
  requestsArg: string,
  port: number,
  timeoutMs: number,
  strategyArg?: string,
): Promise<never> {
  const requestsFile = path.resolve(requestsArg);

  // 比较策略（可选）：先读取并严格校验；失败退出 2，不发任何请求
  let strategy: JsonCompareStrategy | undefined;
  if (strategyArg !== undefined) {
    const strategyFile = path.resolve(strategyArg);
    try {
      strategy = await loadStrategyFromFile(strategyFile);
    } catch (e) {
      process.stderr.write(`${APP_NAME}: replay 比较策略：${describeError(e)}\n`);
      process.exit(2);
    }
  }

  // 参数与全部记录有效后才连接：任何快照错误都不发任何请求
  let requests: ReplayRequest[];
  try {
    requests = await loadReplaySnapshotFromFile(requestsFile);
  } catch (e) {
    process.stderr.write(`${APP_NAME}: replay 请求快照：${describeError(e)}\n`);
    process.exit(2);
  }

  // 策略选中的记录：计划正文须为 UTF-8 JSON（仅可剥离单个开头 BOM，空正文
  // 非法），忽略规则不豁免解析；计划侧对齐位置存在时须为合法对齐数组
  // （位置不存在允许）。与策略、快照一起全部校验通过后才连接
  interface JsonPlan {
    readonly endpoint: JsonCompareEndpoint;
    readonly planned: unknown;
    // 对齐位置 -> 计划侧已校验的 键 -> 元素 映射（仅含计划正文中存在的位置）
    readonly plannedKeys: ReadonlyMap<string, Map<string, AlignKeyEntry>>;
  }
  const jsonPlans: (JsonPlan | null)[] = requests.map((request, i) => {
    const endpoint = strategy?.get(`${request.method} ${request.path}`);
    if (endpoint === undefined) {
      return null;
    }
    const parsed = parseSemanticJson(request.plannedBody);
    if (!parsed.ok) {
      process.stderr.write(
        `${APP_NAME}: replay 请求快照：请求记录快照文件 ${requestsFile} 校验失败：` +
          `records[${i}].plannedResponse.body ${parsed.reason}` +
          `（策略为 ${request.method} ${request.path} 选择 JSON 语义比较）\n`,
      );
      process.exit(2);
    }
    const plannedKeys = new Map<string, Map<string, AlignKeyEntry>>();
    for (const spec of endpoint.align.values()) {
      const checked = checkAlignTarget(parsed.value, spec);
      if (checked === null) {
        continue; // 位置不存在允许
      }
      if ('problem' in checked) {
        process.stderr.write(
          `${APP_NAME}: replay 请求快照：请求记录快照文件 ${requestsFile} 校验失败：` +
            `records[${i}].plannedResponse.body 的对齐位置 ${JSON.stringify(spec.pointer)}` +
            `（键字段 ${JSON.stringify(spec.key)}）非法：正文位置 ${JSON.stringify(checked.problem.pointer)}：` +
            `${checked.problem.reason}\n`,
        );
        process.exit(2);
      }
      plannedKeys.set(spec.pointer, checked.keys);
    }
    return { endpoint, planned: parsed.value, plannedKeys };
  });

  // 按输入顺序保留原编号逐条重放：前一条结束才发下一条
  const results: ReplayResultEntry[] = [];
  for (const [index, request] of requests.entries()) {
    const exchange = await replayOne(port, request, timeoutMs);
    if (!exchange.ok) {
      results.push({ id: request.id, outcome: 'failed', reason: exchange.reason });
      continue;
    }
    const { response } = exchange;
    // 状态码始终精确比较；不比较响应头
    const statusDiff = response.status !== request.plannedStatus;
    const plan = jsonPlans[index];
    if (plan == null) {
      // 字节比较：仅比较状态码与正文原始字节；计划正文按 UTF-8 编码
      const bodyDiff = !response.body.equals(Buffer.from(request.plannedBody, 'utf8'));
      if (!statusDiff && !bodyDiff) {
        results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
      } else {
        results.push({
          id: request.id,
          outcome: 'different',
          differences: { status: statusDiff, body: bodyDiff },
          planned: {
            status: request.plannedStatus,
            body: { encoding: 'utf-8', content: request.plannedBody },
          },
          response: replayResponseJson(response),
        });
      }
      continue;
    }

    // JSON 语义比较：不依赖媒体类型；实际完整响应非 UTF-8 或非 JSON 记正文
    // 差异（说明原因）并继续后续记录
    let bodyDiff: boolean;
    let bodyDifferences: BodyDifference[] | undefined;
    let alignedDifferences: AlignedDifference[] | undefined;
    let alignmentErrors: AlignProblem[] | undefined;
    let bodyError: string | undefined;
    const decoded = decodeUtf8Strict(response.body);
    const actual = decoded.ok ? parseSemanticJson(decoded.text) : decoded;
    if (!actual.ok) {
      bodyDiff = true;
      bodyError = `实际响应正文${actual.reason}，无法进行 JSON 语义比较`;
    } else {
      // 实际侧对齐校验：位置存在时须为合法对齐数组；非法记正文差异（说明位置
      // 与原因）并继续，不算通信失败；该位置回退为按下标比较，其余位置不受影响
      const actualKeys = new Map<string, Map<string, AlignKeyEntry>>();
      const alignProblems: AlignProblem[] = [];
      for (const spec of plan.endpoint.align.values()) {
        const checked = checkAlignTarget(actual.value, spec);
        if (checked === null) {
          continue; // 位置不存在允许
        }
        if ('problem' in checked) {
          alignProblems.push(checked.problem);
        } else {
          actualKeys.set(spec.pointer, checked.keys);
        }
      }
      const out: BodyDiffOut = { differences: [], aligned: [] };
      diffJsonValues(
        plan.planned,
        actual.value,
        {
          ignore: plan.endpoint.ignore,
          align: plan.endpoint.align,
          plannedKeys: plan.plannedKeys,
          actualKeys,
        },
        [],
        [],
        out,
      );
      bodyDiff =
        out.differences.length > 0 || out.aligned.length > 0 || alignProblems.length > 0;
      if (out.differences.length > 0) {
        bodyDifferences = out.differences;
      }
      if (out.aligned.length > 0) {
        alignedDifferences = out.aligned;
      }
      if (alignProblems.length > 0) {
        alignmentErrors = alignProblems;
      }
    }
    if (!statusDiff && !bodyDiff) {
      results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
    } else {
      results.push({
        id: request.id,
        outcome: 'different',
        differences: { status: statusDiff, body: bodyDiff },
        // 差异项保留计划与实际正文的无损表示
        ...(bodyDifferences === undefined ? {} : { bodyDifferences }),
        ...(alignedDifferences === undefined ? {} : { alignedDifferences }),
        ...(alignmentErrors === undefined ? {} : { alignmentErrors }),
        ...(bodyError === undefined ? {} : { bodyError }),
        planned: {
          status: request.plannedStatus,
          body: { encoding: 'utf-8', content: request.plannedBody },
        },
        response: replayResponseJson(response),
      });
    }
  }

  const same = results.filter((r) => r.outcome === 'same').length;
  const different = results.filter((r) => r.outcome === 'different').length;
  const failed = results.filter((r) => r.outcome === 'failed').length;
  const report: ReplayReport = {
    requestsFile,
    port,
    timeoutMs,
    total: results.length,
    same,
    different,
    failed,
    results,
  };
  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  // 空快照或全部相同退出 0；存在差异或通信失败退出 1
  process.exit(different === 0 && failed === 0 ? 0 : 1);
}

// ---------------------------------------------------------------------------
// 离线响应分支可达性诊断（reach 子命令）
// ---------------------------------------------------------------------------
//
// 读取一份通过与 serve 完全相同严格校验的场景配置与一个 POST 接口的字面路径，
// 离线诊断该接口 branches 中每一分支及兜底 responses 是否可达：
//   reachable      —— 存在通过正文检查的请求正文，且该正文首先命中此支；
//   covered        —— 存在满足此支条件的合格正文，但它们全部首先命中前序分支
//                      （遮挡按前序分支的命中并集判定，不是单支包含，也不抽样）；
//   contradictory  —— 条件与正文规则矛盾，不存在满足条件的合格正文。
// 不监听、不发送请求、不修改任何文件。可达分支/兜底各给一份完整请求样例
// （方法、路径、必要头、原始 JSON 正文，补全全部必填字段），样例须通过正文
// 检查并实际选中所报分支或兜底。
//
// 诊断范围（超出即整份拒绝，退出 2）：
// - 接口必须是 POST、声明了非空 branches；
// - 根 requestBody 必须是 object（可附 nullable）；
// - 每个 when 指针可为多段，但每段都必须对应所在对象**已声明的自有字段**，
//   中间节点必须是 object，终点必须是现有标量字段（根指针 ""、穿过数组或
//   标量、未声明字段、object/array 终点均拒绝）；未被任何条件引用的字段、
//   对象与数组仍完全按现有递归规则参与“合格正文”的构造与判定。
//   各层空字段名、__proto__、~0/~1 转义按原语义处理。
//
// 共享祖先的条件作用于同一对象；可选祖先缺失、可空祖先为 null 时，深入它的
// 条件均不匹配（不能把叶字段视为独立维度）；后代必填只在父对象存在且非 null
// 时生效，叶值 null、祖先 null 与祖先缺失分开判定。
//
// 判定精确依据现有 type/enum/nullable/必填可选/额外字段语义：缺失与 null 分开、
// 0 与 -0 等价、不转换类型；根可空时 JSON null 也参与兜底可达性判断。

class ReachError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ReachError';
  }
}

type BranchReachStatus = 'reachable' | 'covered' | 'contradictory';

interface ReachExample {
  readonly method: 'POST';
  readonly path: string;
  readonly headers: { readonly 'Content-Type': 'application/json' };
  readonly body: string;
}

interface ReachReason {
  readonly pointer: string;
  readonly message: string;
}

interface BranchReach {
  readonly id: string;
  readonly status: BranchReachStatus;
  readonly example?: ReachExample;
  // covered：共同遮挡此支的前序分支标识（不必最小）
  readonly coveredBy?: readonly string[];
  readonly message?: string;
  // contradictory：定位到具体条件指针的矛盾原因（可多条）
  readonly reasons?: readonly ReachReason[];
}

interface FallbackReach {
  readonly status: 'reachable' | 'covered';
  readonly example?: ReachExample;
  readonly coveredBy?: readonly string[];
  readonly message?: string;
}

interface ReachReport {
  readonly configFile: string;
  readonly method: 'POST';
  readonly path: string;
  readonly branches: readonly BranchReach[];
  readonly fallback: FallbackReach;
  readonly unreachableBranches: number;
}

// 找不到见证正文的哨兵：不能用 null——根可空时 JSON null 本身就是合法见证
const NO_WITNESS: unique symbol = Symbol('reach-no-witness');
type Witness = unknown | typeof NO_WITNESS;

// 标量条件的非 null 值是否满足字段标量规则的“类型”部分（不做类型转换）
function scalarTypeConforms(
  rule: Extract<BodyRule, { kind: ScalarKind }>,
  value: string | number | boolean,
): boolean {
  switch (rule.kind) {
    case 'string':
      return typeof value === 'string';
    case 'boolean':
      return typeof value === 'boolean';
    case 'number':
      return typeof value === 'number' && Number.isFinite(value);
    case 'integer':
      return Number.isInteger(value);
    case 'null':
      return false;
  }
}

// 条件值与标量字段规则的矛盾原因；无矛盾返回 null。
// 严格按现有语义：类型不符只报类型；类型相符但不在枚举报枚举；
// null 仅当规则接受 null（nullable 且枚举含 null，或 type:"null"）才可行。
function scalarConditionConflict(
  rule: Extract<BodyRule, { kind: ScalarKind }>,
  value: BranchConditionValue,
): { kind: 'type' | 'enum' | 'null' } | null {
  if (value === null) {
    return ruleAcceptsNullValue(rule) ? null : { kind: 'null' };
  }
  if (!scalarTypeConforms(rule, value)) {
    return { kind: 'type' };
  }
  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
    return { kind: 'enum' };
  }
  return null;
}

// 标量维度的一个与全部被引用常量都不同的合格“其余值”（枚举取未被引用候选；
// 无枚举时构造）。任意两个未被引用的合格值对全部等值条件不可区分，故该代表
// 值与缺失、null 一起构成精确有限域，不是抽样；没有合格其余值时返回 undefined。
function freshScalarValue(
  rule: Extract<BodyRule, { kind: ScalarKind }>,
  referenced: ReadonlySet<unknown>,
): unknown {
  if (rule.enum !== undefined) {
    return rule.enum.find((candidate) => candidate !== null && !referenced.has(candidate));
  }
  if (rule.kind === 'boolean') {
    return !referenced.has(false) ? false : !referenced.has(true) ? true : undefined;
  }
  if (rule.kind === 'null') {
    return undefined;
  }
  if (rule.kind === 'string') {
    for (let i = 0; ; i += 1) {
      const candidate = i === 0 ? 'contractlab' : `contractlab_${i}`;
      if (!referenced.has(candidate)) {
        return candidate;
      }
    }
  }
  // number / integer：取未被引用的最小非负整数（integer 合法；number 也合法）
  for (let i = 0; ; i += 1) {
    if (!referenced.has(i)) {
      return i;
    }
  }
}

// 约束树节点：根对象或某个被条件经多段指针穿过的中间 object 字段。
// 共享祖先的全部条件（作用于同一对象的字段指针）汇聚到同一节点，
// 例如 /buyer/state 与 /buyer/flag 的 buyer 是同一节点，不能把叶字段视为
// 互相独立的顶层维度。
class ReachNode {
  readonly objectRule: Extract<BodyRule, { kind: 'object' }>;
  // 从根到本节点的对象字段名序列（根为空数组）
  readonly path: readonly string[];
  readonly parent: ReachNode | null;
  // 本节点挂在父对象上的字段名（根为 null）
  readonly fieldName: string | null;
  // 本对象上被条件直接引用的标量子字段名 -> 该字段的标量规则
  readonly scalarFields = new Map<string, Extract<BodyRule, { kind: ScalarKind }>>();
  // 本对象上被条件穿过的 object 子字段名 -> 子节点
  readonly children = new Map<string, ReachNode>();

  constructor(
    objectRule: Extract<BodyRule, { kind: 'object' }>,
    path: readonly string[],
    parent: ReachNode | null,
    fieldName: string | null,
  ) {
    this.objectRule = objectRule;
    this.path = path;
    this.parent = parent;
    this.fieldName = fieldName;
  }
}

// 钉值：某 RFC 6901 指针处必须严格等于某常量。以规范指针串为键，
// 使不同分支在同一指针上的钉值可以比较/合并。
interface ReachPin {
  readonly pointer: string;
  readonly segments: readonly string[];
  readonly value: BranchConditionValue;
}
type PinMap = ReadonlyMap<string, ReachPin>;

// 一支的条件分析：无矛盾时给出指针 -> 常量的钉值表；矛盾时给出按完整
// RFC 6901 指针定位的原因。
interface BranchAnalysis {
  readonly ok: boolean;
  readonly pins?: PinMap;
  readonly reasons?: readonly ReachReason[];
}

// 同一标量维度上的多个条件常量必须两两严格相等（0 与 -0 视为相等）。
function distinctConstants(values: readonly BranchConditionValue[]): BranchConditionValue[] {
  const distinct: BranchConditionValue[] = [];
  for (const v of values) {
    if (!distinct.some((d) => d === v)) {
      distinct.push(v);
    }
  }
  return distinct;
}

// 重建节点 + 叶字段名对应的规范 RFC 6901 指针
function reachPointer(node: ReachNode, leafName: string): string {
  return `/${[...node.path, leafName].map(escapePointerSegment).join('/')}`;
}

function analyzeBranchConditions(branch: BranchSpec, rootNode: ReachNode): BranchAnalysis {
  // 以“所在节点 + 叶字段名”（即规范指针）为标量维度聚合一支的全部常量
  const groups = new Map<string, {
    node: ReachNode;
    name: string;
    values: BranchConditionValue[];
  }>();
  for (const condition of branch.conditions) {
    let node = rootNode;
    for (let k = 0; k < condition.segments.length - 1; k += 1) {
      node = node.children.get(condition.segments[k]) as ReachNode;
    }
    const name = condition.segments[condition.segments.length - 1];
    const key = reachPointer(node, name);
    const group = groups.get(key);
    if (group === undefined) {
      groups.set(key, { node, name, values: [condition.value] });
    } else {
      group.values.push(condition.value);
    }
  }

  const reasons: ReachReason[] = [];
  const pins = new Map<string, ReachPin>();
  for (const [pointer, group] of groups) {
    const scalarRule = group.node.scalarFields.get(group.name) as Extract<BodyRule, { kind: ScalarKind }>;
    const distinct = distinctConstants(group.values);
    if (distinct.length > 1) {
      reasons.push({
        pointer,
        message: `同一指针上的等值条件值 ${JSON.stringify(distinct)} 互不相容（严格相等、不做类型转换），没有正文能同时满足`,
      });
      continue;
    }

    const value = distinct[0];
    const conflict = scalarConditionConflict(scalarRule, value);
    if (conflict === null) {
      pins.set(pointer, {
        pointer,
        segments: [...group.node.path, group.name],
        value,
      });
      continue;
    }
    if (conflict.kind === 'type') {
      reasons.push({
        pointer,
        message: `条件值 ${JSON.stringify(value)} 与该字段的 ${scalarRule.kind} 规则矛盾（不做类型转换），不存在在此指针处等于该值的合格正文`,
      });
    } else if (conflict.kind === 'enum') {
      reasons.push({
        pointer,
        message: `条件值 ${JSON.stringify(value)} 不在该字段枚举 ${JSON.stringify(scalarRule.enum)} 之中，不存在在此指针处等于该值的合格正文`,
      });
    } else {
      reasons.push({
        pointer,
        message: '条件要求该字段为 JSON null，但字段规则不接受 null；祖先或字段缺失也不等于显式 null，不存在满足该条件的合格正文',
      });
    }
  }

  return reasons.length === 0 ? { ok: true, pins } : { ok: false, reasons };
}

// 标量维度：某对象节点上一个被条件引用的标量子字段的取值域。
interface ReachDim {
  readonly node: ReachNode;
  readonly name: string;
  // 字段“存在且非 null”时的代表值（钉值在求解时单独注入，不在此枚举）
  readonly values: readonly unknown[];
  // 显式 JSON null 是否为合格取值（与“缺失”不同）
  readonly nullable: boolean;
  // 字段是否可缺省
  readonly optional: boolean;
}

// 在根对象规则与全部分支条件之上做精确的有限域可达性求解。
//
// 多段对象指针形成一棵约束树；每个被引用的标量字段是一个维度，取值域为
// {缺失?，null?，各分支钉过的合格常量，一个合格其余值}。中间对象字段按布局
// （缺失?/null?/存在）递归枚举；未被任何条件引用的字段、对象与数组都不在维度
// 中，而以最小合格样本参与——后代必填只在父对象存在且非 null 时才生效。
// 该有限域对等值条件与首支命中精确（不是抽样）：任意两个“其余值”对全部条件
// 不可区分，未引用子树只影响合格性，其最小样本在任一布局下与合格性恒等。
class ReachSolver {
  private readonly rootRule: Extract<BodyRule, { kind: 'object' }>;
  private readonly branches: readonly BranchSpec[];
  private readonly rootNode: ReachNode;
  private readonly dims: readonly ReachDim[];

  constructor(rootRule: Extract<BodyRule, { kind: 'object' }>, branches: readonly BranchSpec[]) {
    this.rootRule = rootRule;
    this.branches = branches;
    this.rootNode = this.buildTree();
    this.dims = this.buildDims();
  }

  // 按全部条件建立对象约束树（范围预检已保证字段链合法）。
  private buildTree(): ReachNode {
    const root = new ReachNode(this.rootRule, [], null, null);
    for (const branch of this.branches) {
      for (const condition of branch.conditions) {
        let node = root;
        let objectRule = this.rootRule;
        for (let k = 0; k < condition.segments.length; k += 1) {
          const name = condition.segments[k];
          const field = objectRule.fields.get(name) as FieldRule;
          if (k === condition.segments.length - 1) {
            node.scalarFields.set(name, field.rule as Extract<BodyRule, { kind: ScalarKind }>);
          } else {
            let child = node.children.get(name);
            if (child === undefined) {
              child = new ReachNode(
                field.rule as Extract<BodyRule, { kind: 'object' }>,
                [...node.path, name],
                node,
                name,
              );
              node.children.set(name, child);
            }
            node = child;
            objectRule = field.rule as Extract<BodyRule, { kind: 'object' }>;
          }
        }
      }
    }
    return root;
  }

  private buildDims(): ReachDim[] {
    // 维度按首次被引用的顺序登记（分支/条件配置顺序），以规范指针去重
    const order: Array<{ pointer: string; segments: readonly string[] }> = [];
    const seen = new Set<string>();
    for (const branch of this.branches) {
      for (const condition of branch.conditions) {
        if (!seen.has(condition.pointer)) {
          seen.add(condition.pointer);
          order.push({ pointer: condition.pointer, segments: condition.segments });
        }
      }
    }

    return order.map(({ pointer, segments }) => {
      const node = this.nodeOf(segments);
      const name = segments[segments.length - 1];
      const scalarRule = node.scalarFields.get(name) as Extract<BodyRule, { kind: ScalarKind }>;
      const field = node.objectRule.fields.get(name) as FieldRule;
      const ref = new Set<unknown>();
      const values: unknown[] = [];
      const push = (v: unknown): void => {
        if (!ref.has(v)) {
          ref.add(v);
          values.push(v);
        }
      };
      // 各分支钉过且合格的常量
      for (const branch of this.branches) {
        for (const condition of branch.conditions) {
          if (condition.pointer !== pointer) {
            continue;
          }
          if (scalarConditionConflict(scalarRule, condition.value) === null) {
            push(condition.value);
          }
        }
      }
      // 一个与全部钉值不同的合格其余值（无则省略，如枚举候选已被全部钉住）
      const rest = freshScalarValue(scalarRule, ref);
      if (rest !== undefined) {
        push(rest);
      }
      return {
        node,
        name,
        values,
        nullable: ruleAcceptsNullValue(scalarRule),
        optional: !field.required,
      };
    });
  }

  private nodeOf(segments: readonly string[]): ReachNode {
    let node = this.rootNode;
    for (let k = 0; k < segments.length - 1; k += 1) {
      node = node.children.get(segments[k]) as ReachNode;
    }
    return node;
  }

  // 一支条件是否被正文全部满足：沿指针取值，取不到（祖先缺失、祖先为 null、
  // 在标量/数组上深入、字段缺失）即不匹配；严格相等、不做类型转换。
  private satisfies(conditions: readonly BranchCondition[], value: unknown): boolean {
    for (const condition of conditions) {
      const actual = resolvePointer(value, condition.segments);
      if (actual === undefined || actual !== condition.value) {
        return false;
      }
    }
    return true;
  }

  private firstMatch(value: unknown): number | null {
    for (let i = 0; i < this.branches.length; i += 1) {
      if (this.satisfies(this.branches[i].conditions, value)) {
        return i;
      }
    }
    return null;
  }

  // 某节点对象的最小合格样本：含全部必填字段（含未引用的对象/数组/标量字段，
  // 递归取最小合格值）；字段名可能为 "" 或 "__proto__"，用无原型对象。
  private baseObject(node: ReachNode): Record<string, unknown> {
    const obj: Record<string, unknown> = Object.create(null);
    for (const [name, field] of node.objectRule.fields) {
      if (field.required) {
        obj[name] = sampleValue(field.rule);
      }
    }
    return obj;
  }

  private allNodes(): readonly ReachNode[] {
    const out: ReachNode[] = [];
    const walk = (node: ReachNode): void => {
      out.push(node);
      for (const child of node.children.values()) {
        walk(child);
      }
    };
    walk(this.rootNode);
    return out;
  }

  // 按钉值表与谓词枚举合格根对象，返回第一个满足谓词者；都不满足返回 NO_WITNESS。
  private findObject(
    pins: PinMap,
    predicate: (value: unknown) => boolean,
  ): Record<string, unknown> | typeof NO_WITNESS {
    // 每个约束节点一个持久工作对象（节点“存在”布局时挂到父对象对应字段上）
    const work = new Map<ReachNode, Record<string, unknown>>();
    for (const node of this.allNodes()) {
      work.set(node, this.baseObject(node));
    }
    const rootObj = work.get(this.rootNode) as Record<string, unknown>;

    // 中间对象节点（不含根），按深度从小到大枚举/物化（父先于子）
    const innerNodes = this.allNodes().slice(1);
    innerNodes.sort((a, b) => a.path.length - b.path.length);
    // 每节点布局数：可选多一个“缺失”，可空多一个“null”，恒有“存在”。
    // 必填不可空：仅存在；必填可空：null/存在；可选不可空：缺失/存在；
    // 可选可空：缺失/null/存在。
    const layouts = innerNodes.map((node) => {
      const field = (node.parent as ReachNode).objectRule.fields.get(node.fieldName as string) as FieldRule;
      return (field.required ? 0 : 1) + (ruleAcceptsNullValue(field.rule) ? 1 : 0) + 1;
    });
    const state = innerNodes.map(() => 0);
    const existsLayout = (idx: number): number => layouts[idx] - 1;
    const nullLayout = (idx: number): number => {
      const node = innerNodes[idx];
      const field = (node.parent as ReachNode).objectRule.fields.get(node.fieldName as string) as FieldRule;
      // null 布局紧挨在存在之前（可缺失时最前为缺失）
      return ruleAcceptsNullValue(field.rule) ? layouts[idx] - 2 : -1;
    };

    // 按当前布局把全部中间节点自顶向下物化到父对象，并登记“存在且祖先链存在”
    // 的活动节点。每轮都显式删除/写入，避免上一轮的陈旧挂载在父对象重新存在时
    // 复活。
    const active = new Set<ReachNode>();
    const materialize = (): void => {
      active.clear();
      for (let idx = 0; idx < innerNodes.length; idx += 1) {
        const node = innerNodes[idx];
        const parentObj = work.get(node.parent as ReachNode) as Record<string, unknown>;
        const name = node.fieldName as string;
        const layout = state[idx];
        if (layout === existsLayout(idx)) {
          parentObj[name] = work.get(node) as Record<string, unknown>;
          if (node.parent === this.rootNode || active.has(node.parent)) {
            active.add(node);
          }
        } else if (layout === nullLayout(idx)) {
          parentObj[name] = null;
        } else {
          delete parentObj[name];
        }
      }
    };

    const chainActive = (node: ReachNode): boolean => {
      let cur: ReachNode | null = node;
      while (cur !== this.rootNode && cur !== null) {
        if (!active.has(cur)) {
          return false;
        }
        cur = cur.parent;
      }
      return true;
    };

    // 钉值涉及的节点（叶对象自身或其祖先）必须取“存在”布局
    const pinnedNodePaths: Array<readonly string[]> = [];
    for (const pin of pins.values()) {
      pinnedNodePaths.push(pin.segments.slice(0, -1));
    }
    const nodeForcedExists = (node: ReachNode): boolean =>
      pinnedNodePaths.some(
        (p) => p.length >= node.path.length && node.path.every((seg, i) => seg === p[i]),
      );

    const problems: StructureProblem[] = [];
    const check = (): Record<string, unknown> | typeof NO_WITNESS => {
      materialize();
      problems.length = 0;
      checkRule(this.rootRule, rootObj, '', problems);
      if (problems.length === 0 && predicate(rootObj)) {
        return rootObj;
      }
      return NO_WITNESS;
    };

    // 标量维度状态：0 起；可选时首态为缺失，可空时紧接 null，之后依次 values。
    const dimCount = (dim: ReachDim): number =>
      (dim.optional ? 1 : 0) + (dim.nullable ? 1 : 0) + dim.values.length;
    const missingState = (dim: ReachDim): number => (dim.optional ? 0 : -1);
    const nullState = (dim: ReachDim): number => (dim.nullable ? (dim.optional ? 1 : 0) : -1);
    const valueOffset = (dim: ReachDim): number => (dim.optional ? 1 : 0) + (dim.nullable ? 1 : 0);

    const pinAt = (dim: ReachDim): BranchConditionValue | undefined =>
      pins.get(reachPointer(dim.node, dim.name))?.value;

    const enumDims = (dimIdx: number): Record<string, unknown> | typeof NO_WITNESS => {
      if (dimIdx === this.dims.length) {
        return check();
      }
      const dim = this.dims[dimIdx];
      const obj = work.get(dim.node) as Record<string, unknown>;
      const pinned = pinAt(dim);
      // 祖先链不“存在”：该维取值无意义（叶字段不可达），只走一态；
      // 钉值也不会写入，谓词（首支命中）自会排除需要该条件成立的情形。
      if (!chainActive(dim.node)) {
        return enumDims(dimIdx + 1);
      }
      if (pinned !== undefined) {
        obj[dim.name] = pinned;
        return enumDims(dimIdx + 1);
      }
      for (let s = 0; s < dimCount(dim); s += 1) {
        if (s === missingState(dim)) {
          delete obj[dim.name];
        } else if (s === nullState(dim)) {
          obj[dim.name] = null;
        } else {
          obj[dim.name] = dim.values[s - valueOffset(dim)];
        }
        const found = enumDims(dimIdx + 1);
        if (found !== NO_WITNESS) {
          return found;
        }
      }
      return NO_WITNESS;
    };

    const enumInner = (idx: number): Record<string, unknown> | typeof NO_WITNESS => {
      if (idx === innerNodes.length) {
        // 全部中间节点布局已定：先物化并登记活动节点，标量维度再据此判定
        // 其祖先链是否“存在”。
        materialize();
        return enumDims(0);
      }
      const node = innerNodes[idx];
      const forcedExists = nodeForcedExists(node);
      for (let layout = 0; layout < layouts[idx]; layout += 1) {
        // 钉值在该节点（或其后代）上时，缺失/null 布局不可能满足谓词，直接跳过
        if (forcedExists && layout !== existsLayout(idx)) {
          continue;
        }
        state[idx] = layout;
        const found = enumInner(idx + 1);
        if (found !== NO_WITNESS) {
          return found;
        }
      }
      return NO_WITNESS;
    };

    return enumInner(0);
  }

  // 找一份合格正文：根可空且无钉值时先尝试 JSON null（任何字段指针在 null 上
  // 都取不到值、不命中分支），再在对象域上求解；有钉值时只能是对象正文。
  findWitness(pins: PinMap, predicate: (value: unknown) => boolean): Witness {
    if (pins.size === 0 && ruleAcceptsNullValue(this.rootRule)) {
      if (predicate(null)) {
        return null;
      }
    }
    return this.findObject(pins, predicate);
  }

  // 两支钉值是否相容：同一规范指针上常量严格相等（0 与 -0 视为相等）才存在
  // 同时满足两支的正文；不同指针恒相容（含共享祖先下的兄弟字段、不同祖先）。
  private mergePins(a: PinMap, b: PinMap): Map<string, ReachPin> | null {
    const merged = new Map(a);
    for (const [key, pin] of b) {
      const existing = merged.get(key);
      if (existing !== undefined && existing.value !== pin.value) {
        return null;
      }
      merged.set(key, pin);
    }
    return merged;
  }

  private example(value: unknown, routePath: string): ReachExample {
    return {
      method: 'POST',
      path: routePath,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(value),
    };
  }

  solve(routePath: string): { branches: BranchReach[]; fallback: FallbackReach } {
    const analyses = this.branches.map((branch) => analyzeBranchConditions(branch, this.rootNode));

    const branchResults: BranchReach[] = [];
    for (let i = 0; i < this.branches.length; i += 1) {
      const branch = this.branches[i];
      const analysis = analyses[i];
      if (!analysis.ok || analysis.pins === undefined) {
        branchResults.push({ id: branch.id, status: 'contradictory', reasons: analysis.reasons });
        continue;
      }

      // 存在合格正文首先命中此支？
      const direct = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === i);
      if (direct !== NO_WITNESS) {
        branchResults.push({ id: branch.id, status: 'reachable', example: this.example(direct, routePath) });
        continue;
      }

      // 满足此支的合格正文必然首先命中某些前序分支——逐支给出共同遮挡者
      const coveredBy: string[] = [];
      for (let j = 0; j < i; j += 1) {
        const prior = analyses[j];
        if (!prior.ok || prior.pins === undefined) {
          continue;
        }
        const merged = this.mergePins(analysis.pins, prior.pins);
        if (merged === null) {
          continue;
        }
        // 同时满足 i 与 j、且 j 之前所有分支都不命中（首支恰为 j）的合格正文
        const witness = this.findWitness(merged, (value) => this.firstMatch(value) === j);
        if (witness !== NO_WITNESS) {
          coveredBy.push(this.branches[j].id);
        }
      }
      branchResults.push({
        id: branch.id,
        status: 'covered',
        coveredBy,
        message:
          `存在满足本支全部条件的合格正文，但它们首先命中的都是前序分支；` +
          `前序分支 ${JSON.stringify(coveredBy)} 的命中区域并集已覆盖本支，本支永远不会被首先选中`,
      });
    }

    // 兜底：存在任何分支都不命中的合格正文（含根为 JSON null）即可达
    const fallbackBody = this.findWitness(new Map(), (value) => this.firstMatch(value) === null);
    let fallback: FallbackReach;
    if (fallbackBody !== NO_WITNESS) {
      fallback = { status: 'reachable', example: this.example(fallbackBody, routePath) };
    } else {
      const noWitness = NO_WITNESS;
      const coveredBy = this.branches
        .map((branch, j) => {
          const analysis = analyses[j];
          if (!analysis.ok || analysis.pins === undefined) {
            return noWitness;
          }
          const witness = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === j);
          return witness !== noWitness ? branch.id : noWitness;
        })
        .filter((id): id is string => id !== noWitness);
      fallback = {
        status: 'covered',
        coveredBy,
        message:
          `没有任何合格正文落到兜底：全部合格正文都被分支 ${JSON.stringify(coveredBy)} 的命中区域并集覆盖`,
      };
    }

    return { branches: branchResults, fallback };
  }
}

// 选择诊断目标接口并执行范围预检；任何不满足都抛 ReachError（退出 2）
function selectReachEndpoint(
  specs: readonly EndpointSpec[],
  configFile: string,
  routePath: string,
): { endpoint: EndpointSpec; index: number } {
  const postMatches = specs
    .map((endpoint, index) => ({ endpoint, index }))
    .filter((entry) => entry.endpoint.method === 'POST' && entry.endpoint.path === routePath);

  if (postMatches.length === 0) {
    const existing = specs.filter((ep) => ep.method === 'POST').map((ep) => `POST ${ep.path}`);
    throw new ReachError(
      `场景文件 ${configFile} 中不存在 POST 接口 ${JSON.stringify(routePath)}。` +
        (existing.length > 0 ? `现有的 POST 接口：${existing.join('，')}` : '该配置没有 POST 接口'),
    );
  }

  const { endpoint, index } = postMatches[0];
  const where = `endpoints[${index}]`;
  if (endpoint.branches.length === 0) {
    throw new ReachError(
      `${where}（POST ${routePath}）未声明 branches：reach 仅诊断声明了响应分支的接口`,
    );
  }
  if (!endpoint.bodyRule || endpoint.bodyRule.kind !== 'object') {
    throw new ReachError(
      `${where}.requestBody ${endpoint.bodyRule ? `的类型为 "${endpoint.bodyRule.kind}"` : ''}：` +
        'reach 仅支持根 requestBody 为 object（可附 nullable）的分支接口',
    );
  }

  // when 指针范围预检：可为多段，但每段都必须是“所在对象已声明的自有字段”，
  // 中间节点必须为 object，终点必须是现有标量规则。根指针、穿过数组或标量、
  // 未声明字段、对象/数组终点都整份拒绝（其他未引用字段仍按递归规则处理）。
  for (let b = 0; b < endpoint.branches.length; b += 1) {
    const branch = endpoint.branches[b];
    for (const condition of branch.conditions) {
      const condWhere = `${where}.branches[${b}].when[${JSON.stringify(condition.pointer)}]`;
      if (condition.segments.length === 0) {
        throw new ReachError(
          `${condWhere} 是根指针 ""：reach 的条件指针必须指向对象字段（至少一段），根指针超出诊断范围`,
        );
      }
      let objectRule: Extract<BodyRule, { kind: 'object' }> = endpoint.bodyRule;
      for (let k = 0; k < condition.segments.length; k += 1) {
        const name = condition.segments[k];
        const isLast = k === condition.segments.length - 1;
        const field = objectRule.fields.get(name);
        if (!field) {
          throw new ReachError(
            `${condWhere} 的第 ${k} 段 ${JSON.stringify(name)} 不是所在对象的已声明字段：` +
              'reach 仅诊断沿已声明自有字段的条件（未声明字段仍按 additionalProperties 等现有规则处理）',
          );
        }
        if (!isLast) {
          if (field.rule.kind !== 'object') {
            throw new ReachError(
              `${condWhere} 的第 ${k} 段 ${JSON.stringify(name)} 规则类型为 "${field.rule.kind}"：` +
                'reach 的多段指针只能穿过 object 字段（穿过数组或标量超出诊断范围）',
            );
          }
          objectRule = field.rule;
        } else if (field.rule.kind === 'object' || field.rule.kind === 'array') {
          throw new ReachError(
            `${condWhere} 的终点字段 ${JSON.stringify(name)} 规则类型为 "${field.rule.kind}"：` +
              'reach 仅支持终点为标量字段的条件，对象/数组终点超出诊断范围',
          );
        }
      }
    }
  }

  return { endpoint, index };
}

async function runReach(configArg: string, pathArg: string): Promise<never> {
  const configFile = path.resolve(configArg);

  let specs: EndpointSpec[];
  try {
    specs = await loadSpecsFromFile(configFile);
  } catch (e) {
    process.stderr.write(`${APP_NAME}: reach 场景配置：${describeError(e)}\n`);
    process.exit(2);
  }

  let report: ReachReport;
  try {
    const { endpoint } = selectReachEndpoint(specs, configFile, pathArg);
    const rootRule = endpoint.bodyRule as Extract<BodyRule, { kind: 'object' }>;
    const result = new ReachSolver(rootRule, endpoint.branches).solve(endpoint.path);
    const unreachableBranches = result.branches.filter((b) => b.status !== 'reachable').length;
    report = {
      configFile,
      method: 'POST',
      path: endpoint.path,
      branches: result.branches,
      fallback: result.fallback,
      unreachableBranches,
    };
  } catch (e) {
    if (e instanceof ReachError) {
      process.stderr.write(`${APP_NAME}: reach: ${e.message}\n`);
      process.exit(2);
    }
    process.stderr.write(`${APP_NAME}: reach 失败：${describeError(e)}\n`);
    process.exit(2);
  }

  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  // 有不可达分支退出 1；兜底不可达仅作信息，不改变退出码
  process.exit(report.unreachableBranches > 0 ? 1 : 0);
}

