5026	// 场景响应的应用层头：配置头 + 服务器填写的准确版本头（+ 必要时的默认 Content-Type）。
5027	// 不含 Content-Length/Connection/Date/Transfer-Encoding 等传输层自动头。
5028	function buildSceneHeaders(
5029	  item: ResponseSpec,
5030	  version: number,
5031	): { readonly [name: string]: string } {
5032	  const headers = versionHeaders(version);
5033	  let contentTypeSet = false;
5034	  for (const [name, value] of Object.entries(item.headers)) {
5035	    const lower = name.toLowerCase();
5036	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
5037	    if (lower === VERSION_HEADER.toLowerCase()) {
5038	      continue;
5039	    }
5040	    if (lower === 'content-type') {
5041	      contentTypeSet = true;
5042	    }
5043	    headers[name] = value;
5044	  }
5045	  // 文本正文的默认内容类型；配置显式给出时不覆盖
5046	  if (!contentTypeSet && item.body !== '') {
5047	    headers['Content-Type'] = 'text/plain; charset=utf-8';
5048	  }
5049	  return freezeHeaders(headers);
5050	}
