5119	type BodyOutcome = 'received' | 'aborted' | 'too-large';
5120	
5121	interface ReceivedBody {
5122	  readonly outcome: BodyOutcome;
5123	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
5124	  readonly body: Buffer;
5125	}
5126	
5127	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
5128	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
5129	  return new Promise((resolve) => {
5130	    let settled = false;
5131	    let size = 0;
5132	    const chunks: Buffer[] = [];
5133	    const finish = (outcome: BodyOutcome): void => {
5134	      if (!settled) {
5135	        settled = true;
5136	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
5137	      }
5138	    };
5139	    req.on('data', (chunk: Buffer) => {
5140	      size += chunk.byteLength;
5141	      if (size > MAX_BODY_BYTES) {
5142	        finish('too-large');
5143	        writeResponse(
5144	          res,
5145	          413,
5146	          versionHeaders(activeState.version, {
5147	            'Content-Type': 'text/plain; charset=utf-8',
5148	          }),
5149	          'payload too large\n',
5150	        );
5151	        // 等 413 刷出后再断开，避免客户端收不到响应
5152	        res.once('finish', () => req.socket.destroy());
5153	        return;
5154	      }
5155	      chunks.push(chunk);
5156	    });
5157	    req.on('end', () => finish('received'));
5158	    req.on('error', () => finish('aborted'));
5159	    req.on('aborted', () => finish('aborted'));
5160	    res.on('close', () => finish('aborted'));
5161	  });
5162	}
