5164	async function dispatch(
5165	  req: http.IncomingMessage,
5166	  res: http.ServerResponse,
5167	): Promise<void> {
5168	  res.on('error', () => {
5169	    // 写已销毁套接字等错误无需让进程崩溃
5170	  });
5171	
5172	  const method = String(req.method);
5173	  const target = String(req.url ?? '/'); // 含查询串的原始请求目标
5174	  const pathname = target.split('?')[0]; // 查询串不参与匹配
5175	
5176	  const { outcome, body } = await receiveBody(req, res);
5177	  if (outcome !== 'received') {
5178	    // aborted：未完整接收，不匹配、不预留、不推进任何序列，也不创建记录
5179	    // too-large：已回复 413，不创建记录、不消费序列
5180	    return;
5181	  }
5182	
5183	  // 管理范围：/__contractlab 本身及 /__contractlab/ 前缀。
5184	  // 其中所有请求都不记录、不消费业务序列（含未知子路径的 404）。
5185	  if (pathname === ADMIN_BASE || pathname.startsWith(ADMIN_PREFIX)) {
5186	    await handleAdmin(method, pathname, res);
5187	    return;
5188	  }
5189	
5190	  // 完整接收且不在管理范围：此刻创建记录并取得进程内递增编号。
5191	  // 编号只取决于完整接收顺序，与接口序列的消费位置互不相关。
5192	  const state = activeState;
5193	  const record = requestLog.create({
5194	    method,
5195	    target,
5196	    path: pathname,
5197	    rawHeaders: req.rawHeaders,
5198	    body,
5199	    configVersion: state.version,
5200	  });
5201	  attachDeliveryTracking(res, record.id);
5202	
5203	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
5204	  const endpoint =
5205	    method === 'GET' || method === 'POST'
5206	      ? state.endpoints.get(`${method} ${pathname}`)
5207	      : undefined;
5208	
5209	  if (!endpoint) {
5210	    // 未匹配请求：404，不消费、无消费位置
5211	    record.matched = false;
5212	    record.endpoint = `${method} ${pathname}`;
5213	    const planned = buildFrameworkPlanned(
5214	      404,
5215	      state.version,
5216	      'not found\n',
5217	      'text/plain; charset=utf-8',
5218	    );
5219	    record.plannedResponse = planned;
5220	    writePlanned(res, planned, record.id);
5221	    return;
5222	  }
5223	  record.matched = true;
5224	  record.endpoint = endpoint.key;
5225	
5226	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
5227	  // 规则、序列与版本均取自上面同一快照 state。
5228	  let parsedBody: unknown = undefined;
5229	  if (endpoint.bodyRule) {
5230	    const result = validateBodyAndParse(req.headers['content-type'], body, endpoint.bodyRule);
5231	    if ('report' in result) {
5232	      record.bodyValidationPassed = false;
5233	      record.bodyRejection = result.report;
5234	      const planned = buildFrameworkPlanned(
5235	        400,
5236	        state.version,
5237	        `${JSON.stringify(result.report)}\n`,
5238	        'application/json; charset=utf-8',
5239	      );
5240	      record.plannedResponse = planned;
5241	      writePlanned(res, planned, record.id);
5242	      return;
5243	    }
5244	    record.bodyValidationPassed = true;
5245	    parsedBody = result.value;
5246	  }
5247	
5248	  // 校验通过（或无规则）：立即预留。声明了分支时按正文值选择分支序列，
5249	  // 否则使用接口兜底序列；各序列独立计数，消费位置与序列长度对应选中序列。
5250	  const reserved =
5251	    endpoint.branches.length > 0
5252	      ? reserveForBody(endpoint, parsedBody)
5253	      : (() => {
5254	          const r = reserveFromSequence(endpoint.responses, endpoint);
5255	          return { ...r, branchId: null as string | null, sequence: endpoint.responses };
5256	        })();
5257	  record.branchSelection =
5258	    reserved.branchId === null ? { kind: 'fallback' } : { kind: 'branch', id: reserved.branchId };
5259	  record.sequencePosition = reserved.position;
5260	  record.sequenceLength = reserved.sequence.length;
5261	  const planned = buildScenePlanned(reserved.item, state.version);
5262	  record.plannedResponse = planned;
5263	  schedulePlannedResponse(res, planned, reserved.item.delay, record.id);
5264	}
