5358	async function startServer(configArg: string, port: number): Promise<void> {
5359	  configFile = path.resolve(configArg);
5360	
5361	  // 先读配置：配置无效时根本不会创建监听
5362	  activeState = await loadStateFromFile(configFile, 1);
5363	
5364	  server = http.createServer((req, res) => {
5365	    dispatch(req, res).catch(() => {
5366	      try {
5367	        req.socket.destroy();
5368	      } catch {
5369	        // 套接字可能已销毁
5370	      }
5371	    });
5372	  });
5373	
5374	  await new Promise<void>((resolve, reject) => {
5375	    server.once('error', reject);
5376	    // 仅监听本机回环地址
5377	    server.listen(port, '127.0.0.1', resolve);
5378	  });
5379	
5380	  const address = server.address();
5381	  const actualPort = typeof address === 'object' && address ? address.port : port;
5382	  process.stdout.write(
5383	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
5384	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
5385	  );
5386	
5387	  const onSignal = (): void => shutdown();
5388	  process.on('SIGINT', onSignal);
5389	  process.on('SIGTERM', onSignal);
5390	}
