// 尚未发出的延迟响应定时器，关闭时统一取消
const pendingTimers = new Set<ReturnType<typeof setTimeout>>();

// 仍可能产生投递状态事件的跟踪器（attachDeliveryTracking 登记、终态时注销）。
// 正常关闭时先等它们全部落定，确保“最终状态落盘”不遗漏连接关闭引发的 interrupted。
const pendingDeliveryTrackers = new Set<() => void>();

function deliveryTracker(): Promise<void> {
  return new Promise((resolve) => {
    pendingDeliveryTrackers.add(resolve);
  });
}

function settleDeliveryTracker(resolve: () => void): void {
  if (pendingDeliveryTrackers.delete(resolve)) {
    resolve();
  }
}

