}

// 绕开 dirty 合并立即完整写一轮（仅启动串行阶段使用）。
private async writeNow(): Promise<void> {
  const file = this.storeFile as string;
  try {
    await writeRequestStoreAtomic(file, serializeRequestStore(this.nextId, this.records));
