    await chmod(dir, 0o700).catch(() => undefined);
  });

  // 清空的删除结果无法落盘：不得报成功（500 或连接被关闭均可）
  const reply = await sendSoft(server.port, '/__contractlab/requests/clear', { method: 'POST' });
