  assert.equal(store.records.length, 1, '清空未确认：旧记录仍在文件中');
});

test('未启用 --requests-file 时保持进程内行为（不创建文件）', { timeout: 30_000 }, async (t) => {
  const dir = await makeTempDir(t);
