import { spawn } from 'node:child_process';
import { once } from 'node:events';
import path from 'node:path';

const APP = '/Users/Shared/products-20261005/contractlab/b/task017/app.ts';
const cfg = process.argv[2];

async function trial(label) {
  const child = spawn(process.execPath, [APP, 'serve', '-c', cfg, '-p', '0'], { stdio: ['ignore', 'pipe', 'pipe'] });
  let out = '';
  child.stdout.setEncoding('utf8').on('data', (d) => (out += d));
  child.stderr.setEncoding('utf8').on('data', () => {});
  const t0 = Date.now();
  await new Promise((res, rej) => {
    child.on('exit', res);
    child.on('error', rej);
    const timer = setInterval(() => { if (/listening/.test(out)) { clearInterval(timer); res(); } }, 10);
  });
  const port = out.match(/127\.0\.0\.1:(\d+)/)[1];
  // one request
  await new Promise((resolve) => {
    const http = require('node:http');
    http.get({ host: '127.0.0.1', port: Number(port) }, (r) => { r.resume(); r.on('end', resolve); }).on('error', resolve);
  });
  const t1 = Date.now();
  child.kill('SIGTERM');
  const [code, signal] = await once(child, 'exit');
  console.log(`${label}: listen+req=${t1 - t0}ms shutdown=${Date.now() - t1}ms code=${code} signal=${signal}`);
}

await trial('trial-1');
await trial('trial-2');

